// Monograph loader: one line per template section (17 lines), fields separated by "|".
DB.add = function (id, name, tags, text) {
  var lines = text.split("\n").map(function (l) { return l.trim(); }).filter(Boolean);
  DB.drugs[id] = { id: id, name: name, tags: tags.split(/\s+/).filter(Boolean),
    s: lines.map(function (l) { return l.split("|").map(function (f) { f = f.trim(); return f === "-" ? "" : f; }); }) };
  if (DB.order.indexOf(id) < 0) DB.order.push(id);
};
DB.GROUPS.forEach(function (g) { g.ids = g.list.split(",").map(function (n) { return DB.slug(n.trim()); }); });
// National Registry-style question loader: level|drug|question|correct|wrong|wrong|wrong|explanation
DB.Q = DB.Q || [];
DB.addQ = function (text, opt) {
  var cj = !!(opt && opt.cj), scene = !!(opt && opt.scene);
  text.split("\n").forEach(function (l) {
    l = l.trim(); if (!l || l.indexOf("|") < 0) return;
    var f = l.split("|").map(function (x) { return x.trim(); });
    if (f.length !== 8 && f.length !== 9) { if (window.console) console.warn("Bad question line", l); return; }
    var home = f[8] === "home"; DB.Q.push({ i: DB.Q.length, lv: f[0], d: f[1] === "-" ? "" : f[1], q: f[2], a: f[3], w: [f[4], f[5], f[6]], x: f[7], cat: home ? "" : f[8] || "", home: home, cj: cj, scene: scene });
  });
};
// Exam-style item types (NREMT technology-enhanced items / NCLEX NGN):
//   M|level|drugId|question|+correct;;-wrong;;+correct;;...|explanation   multiple response (select all that apply)
//   O|level|drugId|question|first;;second;;third;;...|explanation          ordered response (put in order)
DB.QX = DB.QX || [];
DB.addQX = function (text) {
  text.split("\n").forEach(function (l) {
    l = l.trim(); if (!l || l.indexOf("|") < 0 || l.indexOf("//") === 0) return;
    var f = l.split("|").map(function (x) { return x.trim(); });
    if (f.length !== 6 || (f[0] !== "M" && f[0] !== "O")) { if (window.console) console.warn("Bad item line", l); return; }
    var parts = f[4].split(";;").map(function (x) { return x.trim(); }).filter(Boolean), it = { i: DB.QX.length, t: f[0] === "M" ? "multi" : "order", lv: f[1], d: f[2] === "-" ? "" : f[2], q: f[3], x: f[5], cat: "" };
    if (it.t === "multi") { it.opts = parts.map(function (p) { return p.replace(/^[+-]\s*/, ""); }); it.ok = parts.filter(function (p) { return p.charAt(0) === "+"; }).map(function (p) { return p.replace(/^\+\s*/, ""); }); it.a = it.ok.join("; "); }
    else { it.opts = parts.slice(); it.ok = parts.slice(); it.a = parts.map(function (p, k) { return (k + 1) + ". " + p; }).join("  "); }
    it.w = [];
    DB.QX.push(it);
  });
};
// Registry questions: whole-exam National Registry-style items (not drug-only), grouped by NREMT content domain.
//   S|level|domain|question|correct|wrong|wrong|wrong|explanation         single best answer
//   O|level|domain|question|first;;second;;...(correct order, most important first)|explanation
//   M|level|domain|question|+correct;;-wrong;;+correct;;...|explanation   select all that apply
// domain: airway | cardio | trauma | medical | ops
DB.RQ = DB.RQ || [];
DB.addRQ = function (text) {
  text.split("\n").forEach(function (l) {
    l = l.trim(); if (!l || l.indexOf("|") < 0 || l.indexOf("//") === 0) return;
    var f = l.split("|").map(function (x) { return x.trim(); });
    if (f[0] === "S" && f.length === 9) { DB.RQ.push({ reg: 1, lv: f[1], cat: f[2], d: "", q: f[3], a: f[4], w: [f[5], f[6], f[7]], x: f[8] }); return; }
    if (f[0] === "M" && f.length === 6) {
      var parts = f[4].split(";;").map(function (x) { return x.trim(); }).filter(Boolean), it = { reg: 1, t: "multi", lv: f[1], cat: f[2], d: "", q: f[3], x: f[5], w: [] };
      it.opts = parts.map(function (p) { return p.replace(/^[+-]\s*/, ""); }); it.ok = parts.filter(function (p) { return p.charAt(0) === "+"; }).map(function (p) { return p.replace(/^\+\s*/, ""); }); it.a = it.ok.join("; ");
      DB.RQ.push(it); return;
    }
    if (f[0] === "O" && f.length === 6) {
      var steps = f[4].split(";;").map(function (x) { return x.trim(); }).filter(Boolean);
      DB.RQ.push({ reg: 1, t: "order", prio: 1, lv: f[1], cat: f[2], d: "", q: f[3], x: f[5], w: [], opts: steps.slice(), ok: steps.slice(), a: steps.map(function (p, k) { return (k + 1) + ". " + p; }).join("  ") }); return;
    }
    if (window.console) console.warn("Bad registry line", l);
  });
};
// Unfolding calls (National Registry style): one call, several questions in order, from dispatch and scene size-up to handoff.
//   CASE|level|caseId|title
//   STEP|what happens now (the update)|drugId or -|question|CORRECT|wrong|wrong|wrong|explanation
DB.CASES = DB.CASES || [];
DB.addCases = function (text) {
  var cur = null;
  text.split("\n").forEach(function (l) {
    l = l.trim(); if (!l || l.indexOf("//") === 0) return;
    var f = l.split("|").map(function (x) { return x.trim(); });
    if (f[0] === "CASE" && f.length === 4) { cur = { lv: f[1], id: f[2], title: f[3], steps: [] }; DB.CASES.push(cur); return; }
    if (f[0] === "STEP" && f.length === 9 && cur) { cur.steps.push({ story: f[1], d: f[2] === "-" ? "" : f[2], q: f[3], a: f[4], w: [f[5], f[6], f[7]], x: f[8] }); return; }
    if (window.console) console.warn("Bad case line", l);
  });
};
// Drug extensions: id|patient education|nursing considerations|citation;;citation;;...
DB.EXT = DB.EXT || {};
DB.addExt = function (text) {
  text.split("\n").forEach(function (l) {
    l = l.trim(); if (!l || l.indexOf("|") < 0) return;
    var f = l.split("|").map(function (x) { return x.trim(); });
    if (f.length !== 4) { if (window.console) console.warn("Bad ext line", l); return; }
    DB.EXT[f[0]] = { edu: f[1], nurse: f[2], cites: f[3].split(";;").map(function (x) { return x.trim(); }).filter(Boolean) };
  });
};

// Spanish content + pronunciation: id|phonetic|nombre|qué es|para qué se usa|no dar si|dosis adulto|vigilar|recordar|educación al paciente
DB.ES = DB.ES || {};
