DB.scopeFor = function (levelKey) {
  var ids = {}, notes = {};
  var target = DB.LEVELS.map(function (l) { return l.key; }).indexOf(levelKey);
  for (var i = 0; i < DB.LEVELS.length; i++) {
    var k = DB.LEVELS[i].key, m = DB.SCOPE[k];
    // Basic-level notes (EMT/AEMT limits) only show at the basic levels.
    var keepNotes = target < 2 || i >= 2;
    Object.keys(m).forEach(function (id) { ids[id] = true; if (m[id] && keepNotes) notes[id] = m[id]; });
    if (k === levelKey) break;
  }
  return { ids: Object.keys(ids), notes: notes };
};

