DB._ncache = {};
DB.nscopeFor = function (key) {
  if (DB._ncache[key]) return DB._ncache[key];
  var ids = {};
  var all = Object.keys(DB.drugs);
  DB.NSCOPE_CNA.forEach(function (id) { ids[id] = 1; });
  if (key === "lvn" || key === "rn") {
    all.forEach(function (id) { if (DB.drugs[id].tags.indexOf("HM") >= 0 && (DB.MEDIDS || []).indexOf(id) < 0) ids[id] = 1; });
    ["ceftriaxone", "betamethasone", "vancomycin", "heparin", "glucagon", "dextrose", "naloxone", "epinephrine", "ondansetron", "promethazine",
     "ketorolac", "diphenhydramine", "methylprednisolone", "digoxin", "potassium-chloride", "gentamicin", "insulin-nph", "docusate", "sennosides",
     "ferrous-sulfate", "nitrofurantoin", "alendronate", "magnesium-hydroxide", "calcium-carbonate", "guaifenesin"].forEach(function (id) { ids[id] = 1; });
  }
  if (key === "rn") all.forEach(function (id) { ids[id] = 1; });
  var skip = DB.nurseSkip();
  ids = Object.keys(ids).filter(function (id) { return DB.drugs[id] && !skip[id]; });
  var notes = {}, m = DB.NNOTES[key];
  ids.forEach(function (id) { if (m[id]) notes[id] = m[id]; else if (m._all) notes[id] = m._all; });
  return (DB._ncache[key] = { ids: ids, notes: notes });
};

