DB.nurseSkip = function () {
  if (DB._nskip) return DB._nskip;
  var skip = {}, keep = {}; DB.NURSE_KEEP.forEach(function (id) { keep[id] = 1; });
  (DB.MEDIDS || []).forEach(function (id) { if (!keep[id]) skip[id] = 1; });
  DB.GROUPS.forEach(function (g) { if (g.name === "Rare & Specialty Medications" || g.name === "Inhaled Anesthetics") g.ids.forEach(function (id) { if (!keep[id]) skip[id] = 1; }); });
  ["somatostatin", "glucarpidase", "uridine-triacetate", "reteplase", "pancuronium"].concat(DB.IMAGING_ONLY || [], ["caffeine-citrate", "poractant-alfa", "alprostadil", "indomethacin"]).forEach(function (id) { skip[id] = 1; });
  return (DB._nskip = skip);
};
