DB.nunitIds = function (key, level) {
  var u = DB.NUNITS.filter(function (x) { return x.key === key; })[0]; if (!u) return [];
  var ids = {};
  (u.groups || []).forEach(function (n) { DB.GROUPS.forEach(function (g) { if (g.name === n) g.ids.forEach(function (id) { ids[id] = 1; }); }); });
  if (u.tag) Object.keys(DB.drugs).forEach(function (id) { if (DB.drugs[id].tags.indexOf(u.tag) >= 0) ids[id] = 1; });
  if (u.cna) DB.NSCOPE_CNA.forEach(function (id) { ids[id] = 1; });
  (u.ids || "").split(" ").forEach(function (id) { if (id) ids[id] = 1; });
  var out = Object.keys(ids).filter(function (id) { return DB.drugs[id]; });
  if (level && level !== "rn") { var core = DB.nscopeFor(level).ids; out = out.filter(function (id) { return core.indexOf(id) >= 0; }); }
  return out;
};

